fe'umsa mallattoo_dhageettii:
  { sub: id_fayyadamaa, jti: id_meeshaa, gosa: "qaqqabummaa", exp: amma + 15min }
fe'iinsa kaffaltii mallattoo_haaromsuu:
  { sub: id_fayyadamaa, jti: id_meeshaa, gosa: "haaromsuu", exp: amma + 30d }

