fcm.h1_f:
POST https://fcm.googleapis.com/v1/pirojektoota/<pirojektii>/ergaawwan:erguu
Hayyama: Baatee <oauth2_token>
Qaama: {ergaa: {mallattoo: <meeshaa>, deetaa: {...cufame...}, android: {furtuu_kufaa}}}

fts5.h1_f:
CREATE VIRTUAL TABLE ergaa_fts USING fts5(
  qabiyyee, -- tarjaa mallattoo
  kutaa_id UNINDEXED, .
  tokenize = 'unicode61 balleessuu_qabxii 2'.
);
gaaffii: SELECT rowid FROM ergaa_fts WHERE qabiyyee MATCH 'foo'.

